package br.com.onda;
import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.Bundle;
import android.view.*;
import android.webkit.*;
import android.widget.*;

/** Official mobile website in the foreground only. Downloads use the separate existing analyzer. */
@androidx.media3.common.util.UnstableApi
public class YouTubeActivity extends Activity {
 private LinearLayout holder;private TextView status;private Button formats;private WebView web;private EditText query;private Button voice;private boolean recognizing;private volatile boolean protectionEnabled;private final java.util.concurrent.atomic.AtomicInteger blocked=new java.util.concurrent.atomic.AtomicInteger();
 private String lastUrl="https://m.youtube.com/";private boolean visible;
 static boolean allowed(String raw){try{java.net.URI uri=new java.net.URI(raw);return raw.length()<=4096&&"https".equalsIgnoreCase(uri.getScheme())&&uri.getUserInfo()==null&&uri.getPort()==-1&&MediaLinks.isYoutube(raw);}catch(Exception e){return false;}}
 static String searchUrl(String phrase){String clean=phrase==null?"":phrase.trim();if(clean.isEmpty()||clean.length()>160)return "";return Uri.parse("https://m.youtube.com/results").buildUpon().appendQueryParameter("search_query",clean).build().toString();}
 private void search(){String url=searchUrl(query.getText().toString());if(url.isEmpty()){status.setText("Diga ou digite o nome de uma música ou artista, até 160 caracteres.");return;}((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(query.getWindowToken(),0);load(url);status.setText("Pesquisando no YouTube…");}
 private void listen(){if(recognizing)return;recognizing=true;voice.setEnabled(false);if(!VoiceSearch.start(this,false,"Diga o nome da música ou artista para buscar no YouTube")){recognizing=false;voice.setEnabled(true);status.setText("Busca por voz indisponível. Digite no campo acima ou use o microfone do teclado.");}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=VoiceSearch.REQUEST)return;recognizing=false;voice.setEnabled(true);String phrase=VoiceSearch.result(result,data);if(result!=RESULT_OK){status.setText("Busca por voz cancelada. Você pode tentar novamente ou digitar.");return;}if(searchUrl(phrase).isEmpty()){status.setText("Nenhuma busca válida reconhecida. Tente novamente ou digite até 160 caracteres.");return;}query.setText(phrase);query.setSelection(query.length());search();}
 static String downloadUrl(String raw){try{return DownloadLinks.resolve(raw);}catch(Exception e){return "";}}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);protectionEnabled=getSharedPreferences(YouTubeProtection.PREF,0).getBoolean(YouTubeProtection.KEY,true);if(saved!=null&&allowed(saved.getString("url","")))lastUrl=saved.getString("url");LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);Ui.background(root);root.setOnApplyWindowInsetsListener((v,i)->{root.setPadding(Ui.dp(this,12),Ui.dp(this,8)+i.getSystemWindowInsetTop(),Ui.dp(this,12),Ui.dp(this,8)+i.getSystemWindowInsetBottom());return i;});setContentView(root);
  LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);Button back=Ui.button(this,"‹",v->finish());back.setContentDescription("Voltar do YouTube");header.addView(back,new LinearLayout.LayoutParams(Ui.dp(this,48),-2));TextView title=Ui.text(this,"YouTube no Onda",22,Ui.TEXT);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button menu=Ui.menuButton(this,"Menu do YouTube",v->Ui.menu(this,v,new String[]{"Proteção de anúncios: "+(protectionEnabled?"ativa":"desligada"),"Recarregar página","Início do YouTube","Abrir no navegador","Central de downloads"},new String[]{"Proteção de anúncios","Recarregar página","Início do YouTube","Abrir YouTube no navegador","Central de downloads"},new Runnable[]{this::protectionOptions,()->{if(web!=null)web.reload();},()->load("https://m.youtube.com/"),this::external,()->startActivity(new Intent(this,DownloadCenterActivity.class))}));header.addView(menu,new LinearLayout.LayoutParams(-2,-2));root.addView(header);DownloadTabs.add(this,root,true);
  LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);query=new EditText(this);query.setSingleLine(true);query.setTextSize(16);query.setHint("Música ou artista no YouTube");query.setContentDescription("Pesquisar no YouTube");query.setTextColor(Ui.TEXT);query.setHintTextColor(Ui.MUTED);query.setInputType(android.text.InputType.TYPE_CLASS_TEXT);query.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(160)});query.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH);query.setOnEditorActionListener((v,action,event)->{if(action==android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH){search();return true;}return false;});if(saved!=null)query.setText(saved.getString("query",""));row.addView(query,new LinearLayout.LayoutParams(0,Ui.dp(this,52),1));Button submit=Ui.button(this,"⌕",v->search());submit.setTextSize(24);submit.setContentDescription("Buscar no YouTube");row.addView(submit,new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,52)));voice=Ui.voiceButton(this,"Pesquisar YouTube por voz",v->listen());row.addView(voice,new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,52)));root.addView(row);
  status=Ui.text(this,"Escolha um vídeo e consulte os formatos. A disponibilidade depende do YouTube.",12,Ui.MUTED);status.setContentDescription("Estado do YouTube no Onda");root.addView(status);holder=new LinearLayout(this);holder.setOrientation(LinearLayout.VERTICAL);root.addView(holder,new LinearLayout.LayoutParams(-1,0,1));formats=Ui.button(this,"Ver formatos para baixar",v->analyze());formats.setContentDescription("Consultar formatos do vídeo do YouTube");Ui.primary(formats);root.addView(formats,new LinearLayout.LayoutParams(-1,-2));formats.setEnabled(false);
 }
 @android.annotation.SuppressLint("SetJavaScriptEnabled") private void createBrowser(){
  try{web=new WebView(this);WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setJavaScriptCanOpenWindowsAutomatically(false);settings.setSupportMultipleWindows(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);settings.setMediaPlaybackRequiresUserGesture(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);web.setContentDescription("Página oficial do YouTube");
   web.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest request){return filterRequest(request);}@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){String url=request.getUrl().toString();if(allowed(url))return false;if(request.isForMainFrame())status.setText("Esse endereço abre fora da aba do YouTube. Use Abrir no navegador para continuar.");return true;}@Override public void doUpdateVisitedHistory(WebView view,String url,boolean reload){remember(url);}@Override public void onPageFinished(WebView view,String url){remember(url);if(visible&&view==web&&protectionEnabled&&allowed(url))view.evaluateJavascript(YouTubeProtection.cosmeticScript(),null);}@Override public void onReceivedError(WebView view,WebResourceRequest request,WebResourceError error){if(request.isForMainFrame())status.setText("Não foi possível carregar o YouTube. Confira a conexão ou abra no navegador.");}});
   web.setDownloadListener((url,agent,disposition,mime,length)->status.setText("Abra o vídeo e toque em Ver formatos para baixar."));holder.addView(web,new LinearLayout.LayoutParams(-1,-1));web.resumeTimers();web.loadUrl(lastUrl);
  }catch(RuntimeException error){WebView failed=web;web=null;if(failed!=null){holder.removeView(failed);failed.stopLoading();failed.destroy();}status.setText("Atualize o Android System WebView ou abra o YouTube no navegador.");}
 }
 private WebResourceResponse filterRequest(WebResourceRequest request){if(!protectionEnabled||!YouTubeProtection.blocks(request.getUrl().toString(),request.isForMainFrame()))return null;blocked.incrementAndGet();return new WebResourceResponse("text/plain","UTF-8",204,"No Content",java.util.Collections.singletonMap("Cache-Control","no-store"),new java.io.ByteArrayInputStream(new byte[0]));}
 private void protectionOptions(){new AlertDialog.Builder(this).setTitle("Proteção de anúncios").setMessage((protectionEnabled?"Ativa":"Desligada")+" • "+blocked.get()+" solicitações publicitárias bloqueadas nesta sessão.\n\nReduz alguns anúncios e cartões patrocinados. Comerciais dentro dos vídeos ainda podem aparecer. Se uma página parar de funcionar, desative a proteção.\n\nAlterar recarrega a página e pode interromper o vídeo.").setNegativeButton("Fechar",null).setPositiveButton(protectionEnabled?"Desativar e recarregar":"Ativar e recarregar",(d,w)->setProtection(!protectionEnabled)).show();}
 private void setProtection(boolean enabled){protectionEnabled=enabled;getSharedPreferences(YouTubeProtection.PREF,0).edit().putBoolean(YouTubeProtection.KEY,enabled).apply();if(web!=null)web.reload();}
 private void remember(String url){if(!visible||!allowed(url))return;lastUrl=url;formats.setEnabled(!downloadUrl(url).isEmpty());status.setText(downloadUrl(url).isEmpty()?"Escolha um vídeo ou playlist para consultar os formatos.":"Vídeo selecionado • consulte áudio ou vídeo disponíveis.");}
 private void load(String url){if(!allowed(url))return;lastUrl=url;formats.setEnabled(false);if(web!=null)web.loadUrl(url);}
 private void analyze(){String url=downloadUrl(web==null?lastUrl:web.getUrl());if(url.isEmpty()){status.setText("Abra um vídeo ou playlist antes de consultar os formatos.");return;}startActivity(new Intent(this,DownloadsActivity.class).putExtra("analyze_link",url).addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT|Intent.FLAG_ACTIVITY_SINGLE_TOP));}
 private void external(){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(lastUrl)));}catch(ActivityNotFoundException error){status.setText("Nenhum navegador disponível.");}}
 @Override protected void onResume(){super.onResume();visible=true;if(web==null)createBrowser();else{web.onResume();web.resumeTimers();}}
 @Override protected void onPause(){visible=false;if(web!=null){web.evaluateJavascript("document.querySelectorAll('video,audio').forEach(function(m){m.pause();});",null);web.onPause();web.pauseTimers();}super.onPause();}
 @Override protected void onStop(){if(web!=null){WebView old=web;web=null;holder.removeView(old);old.stopLoading();old.destroy();}super.onStop();}
 @Override public void onBackPressed(){if(web!=null&&web.canGoBack())web.goBack();else super.onBackPressed();}
 @Override protected void onSaveInstanceState(Bundle state){state.putString("url",lastUrl);state.putString("query",query.getText().toString());super.onSaveInstanceState(state);}
 @Override protected void onDestroy(){if(web!=null){holder.removeView(web);web.destroy();web=null;}super.onDestroy();}
}
